(async()=>{
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const side=document.querySelector('.stax-side');
const body=side.querySelector('.sd-body');
const vis=e=>{const r=e.getBoundingClientRect();const cs=getComputedStyle(e);return r.width>0&&r.height>0&&cs.visibility!=='hidden'&&cs.display!=='none'};
const out={theme:document.body.getAttribute('data-theme'),vw:innerWidth,vh:innerHeight,open:side.classList.contains('open')};
out.sections=[...side.querySelectorAll('.sd-sec-head')].map(h=>{const rows=h.nextElementSibling;const chev=h.querySelector('.sd-chev');return {name:h.textContent.trim(),ariaExpanded:h.getAttribute('aria-expanded'),rowsVisible:vis(rows),chevTransform:getComputedStyle(chev).transform}});
out.persistKey=localStorage.getItem('stax-drawer-open');
out.tilesStrip=side.querySelectorAll('.sd-tiles,.sd-tile,[aria-label=Shortcuts]').length;
out.pinnedFooter=side.querySelectorAll('.sd-foot,footer').length;
out.order=[...body.children].map(c=>c.getAttribute('aria-label')||c.querySelector('h2')?.textContent||c.className);
out.lastBlock=body.lastElementChild.className;
out.ownerInsideScroll=body.contains(side.querySelector('#sd-owner'));
out.fixedOrSticky=[...side.querySelectorAll('*')].filter(e=>/fixed|sticky/.test(getComputedStyle(e).position)).map(e=>e.className);
